import struct
import zlib


class Frame:
    """Provide frame behavior."""

    def __init__(self, version: int, flags: int, stream_id: int, sequence_number: int, payload: bytes):
        self.version = version
        self.flags = flags
        self.stream_id = stream_id
        self.sequence_number = sequence_number
        self.payload = payload


class Decoder:
    """Provide decoder behavior."""

    def __init__(self, max_buffer_size: int, max_payload_size: int):
        self.max_buffer_size = max_buffer_size
        self.max_payload_size = max_payload_size
        self.buffer = bytearray()
        self.last_sequence_numbers = {}

    def decode_frame(self, data: bytes) -> Frame | None:
        """Decode frame."""
        self.buffer.extend(data)
        while len(self.buffer) >= 10:
            sync_marker_index = self.buffer.find(b'\xaa\xbb')
            if sync_marker_index == -1:
                break
            self.buffer = self.buffer[sync_marker_index:]
            try:
                version, flags, stream_id, sequence_number, payload_length = struct.unpack_from('>HBBHI', self.buffer)
                payload_start = 8
                if payload_length > 0:
                    payload_start += 4
                    compressed_flag = flags & 1 != 0
                    crc32_start = payload_start + payload_length
                    if crc32_start + 4 > len(self.buffer):
                        break
                    frame_crc32 = struct.unpack_from('>I', self.buffer, crc32_start)[0]
                    calculated_crc32 = zlib.crc32(self.buffer[:crc32_start]) & 4294967295
                    if frame_crc32 != calculated_crc32:
                        raise ValueError('CRC32 mismatch')
                    payload = self.buffer[payload_start:crc32_start]
                    if compressed_flag:
                        decompressed_payload = zlib.decompress(payload)
                        if len(decompressed_payload) > self.max_payload_size:
                            raise ValueError('Decompressed payload size exceeds limit')
                        payload = decompressed_payload
                    elif len(payload) > self.max_payload_size:
                        raise ValueError('Payload size exceeds limit')
                frame = Frame(version, flags, stream_id, sequence_number, payload)
                if stream_id in self.last_sequence_numbers and sequence_number <= self.last_sequence_numbers[stream_id]:
                    raise ValueError('Duplicate or out-of-order frame')
                self.last_sequence_numbers[stream_id] = sequence_number
                return frame
            except (struct.error, zlib.error, ValueError) as e:
                self.buffer = self.buffer[1:]
        return None

import unittest
from tech_connector.services.generated.decoder import Decoder
from tech_connector.services.generated.encoder import Encoder


class TestDecoder(unittest.TestCase):

    def setUp(self):
        self.max_buffer_size = 1024 * 1024
        self.max_payload_size = 1024
        self.decoder = Decoder(self.max_buffer_size, self.max_payload_size)
        self.encoder = Encoder(self.max_payload_size)

    def test_valid_frame(self):
        frame = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': b'Hello, World!', 'crc32': 305419896}
        encoded_data = self.encoder.encode_frame(frame)
        decoded_frame = self.decoder.decode_frame(encoded_data)
        self.assertIsNotNone(decoded_frame)
        self.assertEqual(decoded_frame['version'], 1)
        self.assertEqual(decoded_frame['flags'], 0)
        self.assertEqual(decoded_frame['stream_id'], 1)
        self.assertEqual(decoded_frame['sequence_number'], 1)
        self.assertEqual(decoded_frame['payload'], b'Hello, World!')

    def test_invalid_crc(self):
        frame = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': b'Hello, World!'}
        encoded_data = self.encoder.encode_frame(frame)
        encoded_data = encoded_data[:-4] + b'\x00\x00\x00\x00'
        decoded_frame = self.decoder.decode_frame(encoded_data)
        self.assertIsNone(decoded_frame)

    def test_duplicate_sequence_number(self):
        frame1 = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': b'Hello, World!'}
        encoded_data1 = self.encoder.encode_frame(frame1)
        decoded_frame1 = self.decoder.decode_frame(encoded_data1)
        self.assertIsNotNone(decoded_frame1)
        frame2 = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': b'Hello, World!'}
        encoded_data2 = self.encoder.encode_frame(frame2)
        decoded_frame2 = self.decoder.decode_frame(encoded_data2)
        self.assertIsNone(decoded_frame2)

    def test_resynchronization(self):
        frame1 = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': b'Hello, World!'}
        encoded_data1 = self.encoder.encode_frame(frame1)
        frame2 = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 2, 'payload': b'Goodbye, World!'}
        encoded_data2 = self.encoder.encode_frame(frame2)
        noisy_data = b'\x00' * 10 + encoded_data1 + b'\x00' * 5 + encoded_data2
        decoded_frames = []
        while True:
            frame = self.decoder.decode_frame(noisy_data)
            if frame is None:
                break
            decoded_frames.append(frame)
        self.assertEqual(len(decoded_frames), 2)
        self.assertEqual(decoded_frames[0]['sequence_number'], 1)
        self.assertEqual(decoded_frames[1]['sequence_number'], 2)

    def test_sequence_gap_reporting(self):
        frame1 = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': b'Hello, World!'}
        frame3 = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 3, 'payload': b'Goodbye, World!'}
        encoded_data1 = self.encoder.encode_frame(frame1)
        encoded_data3 = self.encoder.encode_frame(frame3)
        noisy_data = encoded_data1 + b'\x00' * 10 + encoded_data3
        decoded_frames = []
        while True:
            frame = self.decoder.decode_frame(noisy_data)
            if frame is None:
                break
            decoded_frames.append(frame)
        self.assertEqual(len(decoded_frames), 2)
        self.assertEqual(decoded_frames[0]['sequence_number'], 1)
        self.assertEqual(decoded_frames[1]['sequence_number'], 3)

    def test_memory_usage_limits(self):
        large_payload = b'A' * (self.max_payload_size + 1)
        frame = {'version': 1, 'flags': 0, 'stream_id': 1, 'sequence_number': 1, 'payload': large_payload}
        encoded_data = self.encoder.encode_frame(frame)
        decoded_frame = self.decoder.decode_frame(encoded_data)
        self.assertIsNone(decoded_frame)


if __name__ == '__main__':
    unittest.main()
